import type { LatLon } from "./map";
import type { AirportLayout, GateIndex } from "./gateIndexData";
import { distanceM } from "./gatePlacement";

/**
 * The static OSM airport layout index, keyed by airport ICAO:
 * `{ ICAO: { gates: { ref: [[lon, lat], ...] }, stands: { ref: [...] } } }`
 * (gateIndexData.ts is generated by scripts/build-gate-index.mjs).
 *
 * The basemap ships `aeroway=gate` points only from tile zoom 14 up, so the
 * runtime tile lookup in map.ts is empty below app zoom 15 (app zoom = MapLibre
 * zoom + 1). This index has no zoom dependency and needs no tile loaded, so a
 * provider-confirmed gate is placed at any zoom. `stands` are the
 * `aeroway=parking_position` objects (remote and cargo stands), so a provider
 * ref that names a stand rather than a gate still resolves.
 *
 * Data © OpenStreetMap contributors, ODbL 1.0.
 */

// The index is a chunk of its own (a dynamic import, the treatment
// worldMapData gets): a selected at-gate plane is the only reader, so it has no
// business in the entry bundle. Until it lands the lookup answers null and the
// app falls back to the basemap's own gate points.
let index: GateIndex | null = null;
let loading: Promise<void> | null = null;

/**
 * Fetch the index chunk. Idempotent; fail-soft (an offline or blocked fetch
 * leaves the index null and the tile fallback in charge). Await it before a
 * lookup whose answer must not miss: the first one after boot.
 */
export function loadGateIndex(): Promise<void> {
  loading ??= import("./gateIndexData").then(
    (mod) => {
      index = mod.GATE_INDEX;
    },
    () => {
      /* no index: the tile path still answers */
    },
  );
  return loading;
}

/** True once the index chunk is in memory. */
export function gateIndexReady(): boolean {
  return index !== null;
}

/**
 * The canonical form of a gate ref: upper-cased, a leading "GATE" word
 * dropped, and every space removed. So the provider refs "D18", "d18",
 * "Gate D18" and "E5 B" fold onto the index keys "D18" / "E5B". The index is
 * generated already folded by the same rule (scripts/build-gate-index.mjs),
 * so only the incoming ref is normalised here.
 */
export function normalizeGateRef(ref: string): string {
  return ref.trim().toUpperCase().replace(/^GATE\b/, "").replace(/\s+/g, "");
}

/**
 * The coordinate of gate or stand `ref` at airport `icao` nearest `near`, or
 * null when the index is not loaded, the airport is not in it, or it carries no
 * such ref.
 *
 * Stands are preferred over gates: a ref OSM carries in both lists is a stand
 * the provider is naming as the gate. A ref can carry several coordinates
 * (EGLL's A-pier refs sit at two terminals), so the nearest to `near` wins —
 * the same rule the tile path uses. Refs that name a range ("59 A-B") carry no
 * separator in the index and are absent on purpose.
 */
export function gateFromIndex(icao: string | null | undefined, ref: string, near: LatLon): LatLon | null {
  const layout = layoutFor(icao);
  if (!layout) return null;
  const key = normalizeGateRef(ref);
  if (!key) return null;
  const points = layout.stands[key] ?? layout.gates[key];
  if (!points || points.length === 0) return null;
  return nearestTo(near, points);
}

/**
 * The stand nearest `near` at airport `icao`, within `maxM` metres, or null.
 * Used only as a fallback for an on-ground plane whose provider ref the index
 * does not carry at all: a plane parked at a remote stand is within a few
 * metres of the stand's own point, a taxiing one is not.
 */
export function nearestStandFromIndex(
  icao: string | null | undefined,
  near: LatLon,
  maxM: number,
): (LatLon & { ref: string }) | null {
  const layout = layoutFor(icao);
  if (!layout) return null;
  let best: { ref: string; lat: number; lon: number; d: number } | null = null;
  for (const [ref, points] of Object.entries(layout.stands)) {
    for (const [lon, lat] of points) {
      const d = distanceM(near, { lat, lon });
      if (d <= maxM && (!best || d < best.d)) best = { ref, lat, lon, d };
    }
  }
  return best ? { ref: best.ref, lat: best.lat, lon: best.lon } : null;
}

function layoutFor(icao: string | null | undefined): AirportLayout | null {
  if (!index || !icao) return null;
  return index[icao.trim().toUpperCase()] ?? null;
}

/** The [lon, lat] of the list nearest `near`. */
function nearestTo(near: LatLon, points: [number, number][]): LatLon {
  let best = points[0];
  let bestD = distanceM(near, { lat: best[1], lon: best[0] });
  for (const [lon, lat] of points.slice(1)) {
    const d = distanceM(near, { lat, lon });
    if (d < bestD) {
      best = [lon, lat];
      bestD = d;
    }
  }
  return { lat: best[1], lon: best[0] };
}
